    }
    const auto& ori = xShape->GetOriginShape();
    uint32_t M = static_cast<uint32_t>(ori.GetDim(0));
    uint32_t N = static_cast<uint32_t>(ori.GetDim(1));

    // Set block dim
    context->SetBlockDim(BLOCK_DIM);

    // Fill tiling data
    MatmulDropoutMeanSoftmaxCustomTilingData tiling;
    tiling.set_rows(M);
    tiling.set_cols(N);
    tiling.set_tileNum(TILE_NUM);

    // Save tiling buffer
    auto* raw = context->GetRawTilingData();
    tiling.SaveToBuffer(raw->GetData(), raw->GetCapacity());
    raw->SetDataSize(tiling.GetDataSize());

    // No workspace needed
    size_t* ws = context->GetWorkspaceSizes(1);
    ws[0] = 0;
    return ge::GRAPH_SUCCESS;
}
